<title>Tickets Confirmed</title>

<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800&amp;display=swap" rel="stylesheet" />

<style>
*{
    margin:0;
    padding:0;
    box-sizing:border-box;
}

body{
    font-family:Inter,sans-serif;
    min-height:100vh;
    display:flex;
    justify-content:center;
    align-items:center;
    background:
        radial-gradient(circle at top,#3c4187 0%,#1b1b36 40%,#090911 100%);
    color:white;
    padding:40px;
}

.card{
    width:460px;
    background:rgba(255,255,255,.08);
    backdrop-filter:blur(20px);
    border:1px solid rgba(255,255,255,.1);
    border-radius:26px;
    overflow:hidden;
    box-shadow:0 25px 60px rgba(0,0,0,.45);
}

.header{
    padding:45px 30px;
    text-align:center;
    background:linear-gradient(135deg,#6a5cff,#3a88ff);
}

.check{
    width:90px;
    height:90px;
    margin:0 auto 20px;
    border-radius:50%;
    background:white;
    color:#4d68ff;
    font-size:52px;
    display:flex;
    align-items:center;
    justify-content:center;
    font-weight:bold;
}

.header h1{
    font-size:34px;
    margin-bottom:10px;
}

.header p{
    opacity:.9;
}

.content{
    padding:30px;
}

.ticket{
    background:rgba(255,255,255,.05);
    border-radius:18px;
    padding:22px;
    margin-bottom:24px;
}

.event{
    font-size:24px;
    font-weight:800;
}

.tour{
    color:#b9bbff;
    margin-top:4px;
}

.info{
    margin-top:22px;
    display:grid;
    gap:14px;
    color:#ddd;
}

.row{
    display:flex;
    justify-content:space-between;
}

.code{
    margin-top:28px;
    padding:18px;
    border-radius:14px;
    background:#11182d;
    text-align:center;
}

.code small{
    color:#999;
    display:block;
    margin-bottom:8px;
}

.code strong{
    font-size:26px;
    letter-spacing:3px;
}

.actions{
    display:grid;
    gap:12px;
    margin-top:28px;
}

button{
    padding:16px;
    border:none;
    border-radius:14px;
    font-size:16px;
    font-weight:700;
    cursor:pointer;
}

.primary{
    background:linear-gradient(90deg,#6a5cff,#3a88ff);
    color:white;
}

.secondary{
    background:rgba(255,255,255,.08);
    color:white;
}
</style>




<div class="card">

    <div class="header">
        <div class="check">✓</div>
        <h1>You're Going!</h1>
        <p>Your tickets have been confirmed.</p>
    </div>

    <div class="content">

        <div class="ticket">

            <div class="event">Wincent Wise</div>
            <div class="tour">Echoes Tour 2026</div>

            <div class="info">

                <div class="row">
                    <span>📍 Venue</span>
                    <span>Munich Arena</span>
                </div>

                <div class="row">
                    <span>📅 Date</span>
                    <span>October 17, 2026</span>
                </div>

                <div class="row">
                    <span>🎟 Tickets</span>
                    <span>2 × General Admission</span>
                </div>

                <div class="row">
                    <span>💳 Paid</span>
                    <span>€102</span>
                </div>

            </div>

        </div>

        <div class="code">
            <small>Booking Reference</small>
            <strong>WW-83K7X2</strong>
        </div>

        <div class="actions">
            <button class="primary">📱 View Mobile Ticket</button>
            <button class="secondary">⬇ Download PDF Ticket</button>
        </div>

    </div>

</div>




